ALTER TABLE "MealPlan" ADD COLUMN "menuDate" TEXT;
INSERT OR IGNORE INTO Exercise (id,nameEn,nameHe,muscle,equipment,difficulty,instructionsEn,instructionsHe) VALUES
('curl', 'Dumbbell curl', 'כפיפת מרפקים עם משקולות', 'arms', 'dumbbells', 'beginner', 'Stand tall with the weights at your sides. Curl without moving your upper arms. Lower slowly.', 'עמדו זקוף עם המשקולות לצדי הגוף. כופפו מרפקים בלי להזיז את הזרועות קדימה. הורידו לאט.'),
('plank', 'Forearm plank', 'פלאנק על האמות', 'core', 'bodyweight', 'beginner', 'Place your elbows under your shoulders. Brace your abdomen and hold a straight line. Breathe steadily.', 'מקמו את המרפקים מתחת לכתפיים. אספו את הבטן ושמרו על קו גוף ישר. המשיכו לנשום בקצב אחיד.'),
('goblet', 'Goblet squat', 'סקוואט גביע', 'legs', 'dumbbells', 'beginner', 'Hold a dumbbell close to your chest. Lower between your hips with your heels down. Push the floor away to stand.', 'החזיקו משקולת צמודה לחזה. רדו בסקוואט כשהעקבים על הרצפה. דחפו את הרצפה וחזרו לעמידה.'),
('legpress', 'Leg press', 'לחיצת רגליים', 'legs', 'gym', 'beginner', 'Place both feet securely on the platform. Lower the platform while keeping your pelvis against the pad. Press without locking your knees.', 'מקמו את שתי כפות הרגליים ביציבות על המשטח. כופפו ברכיים תוך שמירה על האגן צמוד למשענת. דחפו בלי לנעול ברכיים.'),
('extension', 'Seated leg extension', 'פשיטת ברכיים בישיבה', 'legs', 'gym', 'beginner', 'Align the knee with the machine''s pivot. Extend with control. Lower the pad without letting the weights drop.', 'יישרו את הברך עם ציר המכשיר. פשטו את הברכיים בשליטה. הורידו את הכרית בלי להפיל את המשקולות.'),
('hamcurl', 'Lying leg curl', 'כפיפת ברכיים בשכיבה', 'legs', 'gym', 'beginner', 'Lie face down with the pad just above your heels. Bend your knees while keeping your hips down. Lower slowly.', 'שכבו על הבטן כשהכרית מונחת מעט מעל העקבים. כופפו ברכיים בלי להרים את האגן. הורידו לאט.'),
('laterals', 'Dumbbell lateral raise', 'הרחקת כתפיים עם משקולות', 'shoulders', 'dumbbells', 'beginner', 'Hold the dumbbells at your sides. Raise your arms to the sides with soft elbows. Lower without swinging.', 'החזיקו משקולות לצדי הגוף. הרימו את הזרועות לצדדים במרפקים מעט כפופים. הורידו בלי תנופה.'),
('facepull', 'Cable face pull', 'משיכת חבל לפנים', 'shoulders', 'gym', 'intermediate', 'Set the pulley near face height. Pull the rope toward your face and move your hands apart. Return slowly.', 'כוונו את הפולי לגובה הפנים. משכו את החבל לכיוון הפנים והפרידו את כפות הידיים. חזרו לאט.'),
('stepup', 'Step-up with knee raise', 'עלייה למדרגה עם הרמת ברך', 'legs', 'bodyweight', 'intermediate', 'Place one foot fully on a stable step. Step up and lift the opposite knee. Lower under control.', 'הניחו כף רגל שלמה על מדרגה יציבה. עלו והרימו את הברך הנגדית. רדו בשליטה.'),
('cable', 'Seated cable row', 'חתירה בישיבה בפולי', 'back', 'gym', 'beginner', 'Sit tall with knees slightly bent. Pull the handle toward your waist. Extend your arms slowly without rocking.', 'שבו זקוף עם ברכיים מעט כפופות. משכו את הידית לכיוון המותניים. ישרו את הזרועות לאט ובלי להתנדנד.'),
('triceps', 'Cable triceps pushdown', 'פשיטת מרפקים בפולי עליון', 'arms', 'gym', 'beginner', 'Keep the elbows close to your sides. Straighten your arms against the cable. Let the handle return under control.', 'הצמידו את המרפקים לצדי הגוף. ישרו את הזרועות נגד התנגדות הכבל. אפשרו לידית לחזור בשליטה.');
